<?php
namespace Tests\Feature;
use App\Models\{Venue,Owner,User};use App\Services\{VenueSettings,BookingEngine,ChatService};use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Str;use Tests\TestCase;
class ClockTest extends TestCase {
 use RefreshDatabase;
 private function venue(array $settings=[]):Venue{$u=User::factory()->create();$o=Owner::unguarded(fn()=>Owner::create(['user_id'=>$u->id,'name'=>'Dueño','email'=>$u->email,'password'=>'OwnerPassword12345','activated'=>true,'email_verified_at'=>now()]));return Venue::create(['owner_id'=>$u->id,'owner_account_id'=>$o->id,'slug'=>'clock-'.Str::lower(Str::random(7)),'name'=>'Local con minutos','published'=>true,'settings'=>array_replace(VenueSettings::defaults(),['mode'=>'hour','capacity'=>100,'open_hour'=>10,'open_minute'=>30,'close_hour'=>26,'close_minute'=>15,'prep_minutes'=>15,'clean_minutes'=>30,'included_hours'=>1,'weekday_price'=>10000,'weekend_price'=>20000,'holiday_price'=>30000,'extra_hour_price'=>10000,'deposit_value'=>30,'address'=>'Colima','lat'=>19.2,'lng'=>-103.7],$settings)]);}
 private function date():string{return now('America/Mexico_City')->addMonth()->startOfWeek()->addDays(2)->toDateString();}
 public function test_hours_with_minutes_are_saved_and_overnight_hours_remain_compatible():void{$v=$this->venue();$this->actingAs($v->owner)->putJson('/api/owner/venues/'.$v->slug,['name'=>$v->name,'slug'=>$v->slug,'settings'=>$v->settings,'published'=>true])->assertOk()->assertJsonPath('settings.open_minute',30)->assertJsonPath('settings.close_hour',26)->assertJsonPath('settings.close_minute',15);}
 public function test_quotes_respect_opening_preparation_and_minutes():void{$v=$this->venue();$d=['date'=>$this->date(),'start'=>10.75,'hours'=>1,'guests'=>5];$q=$this->postJson('/api/venues/'.$v->slug.'/quote',$d)->assertOk()->json('quote');$this->assertSame('10:45',\Carbon\CarbonImmutable::parse($q['starts_at'])->setTimezone('America/Mexico_City')->format('H:i'));$d['start']=10.5;$this->postJson('/api/venues/'.$v->slug.'/quote',$d)->assertUnprocessable();}
 public function test_availability_returns_minute_slots_and_day_after_midnight():void{$v=$this->venue();$days=$this->getJson('/api/venues/'.$v->slug.'/availability?month='.substr($this->date(),0,7))->assertOk()->json('days');$day=collect($days)->firstWhere('date',$this->date());$this->assertTrue($day['available']);$this->assertContains(10.75,$day['slots']);$this->assertNotContains(10.5,$day['slots']);$this->assertContains(24.75,$day['slots']);}
 public function test_closing_minutes_and_cleanup_are_checked():void{$v=$this->venue(['close_minute'=>0]);$this->postJson('/api/venues/'.$v->slug.'/quote',['date'=>$this->date(),'start'=>24.5,'hours'=>1,'guests'=>5])->assertOk();$this->postJson('/api/venues/'.$v->slug.'/quote',['date'=>$this->date(),'start'=>24.75,'hours'=>1,'guests'=>5])->assertUnprocessable();}
 public function test_legacy_integer_hours_without_minute_keys_still_work():void{$v=$this->venue();$s=$v->settings;unset($s['open_minute'],$s['close_minute']);$v->settings=$s;$v->save();$this->postJson('/api/venues/'.$v->slug.'/quote',['date'=>$this->date(),'start'=>11,'hours'=>1,'guests'=>5])->assertOk();}
 public function test_invalid_closing_and_minute_values_are_rejected():void{$v=$this->venue();$this->actingAs($v->owner);foreach([['close_hour'=>9],['close_minute'=>60],['open_minute'=>-1]] as $bad)$this->putJson('/api/owner/venues/'.$v->slug,['name'=>$v->name,'slug'=>$v->slug,'published'=>true,'settings'=>array_replace($v->settings,$bad)])->assertUnprocessable();}
 public function test_half_hour_after_midnight_uses_the_same_operating_day():void{$v=$this->venue();$this->postJson('/api/venues/'.$v->slug.'/quote',['date'=>$this->date(),'start'=>24.5,'hours'=>1,'guests'=>5])->assertOk()->assertJsonPath('quote.date',$this->date());}
 public function test_chat_formats_minutes_without_technical_hour_numbers():void{$v=$this->venue();$facts=app(ChatService::class)->facts($v,'horarios');$this->assertStringContainsString('10:30',$facts['text']);$this->assertStringContainsString('02:15 del día siguiente',$facts['text']);$this->assertStringNotContainsString('26:',$facts['text']);}
}
